151			newV    want
152		}{
153			{
154				"交接点前1纳秒",
155				handoffPoint.Add(-time.Nanosecond),
156				want{true, 150, 600, ReasonNone},
157				want{false, 0, 0, ReasonVersionNotYetEffective},
158			},
159			{
160				"交接点本身",
161				handoffPoint,
162				want{false, 0, 0, ReasonVersionExpired},
163				want{true, 180, 720, ReasonNone},
164			},
