	if err != nil {
		t.Fatal(err)
	}
	if !out.Confirmed || out.UnitPrice != 150 || out.Total != 600 {
		t.Fatalf("unexpected outcome: %+v", out)
	}
	if !out.AcceptedAt.Equal(at(5)) {
		t.Fatalf("acceptance time: %v", out.AcceptedAt)
	}
	if out.Reason != ReasonNone {
