16	// 登记只按旧版当前的实际有效期判断交接点是否合法，允许交接点早于登记当天，
17	// 因此补登成功后旧版的实际结束被提前到 3 月 10 日零点，
18	// 早于那笔 600 分确认报价的受理时刻。所有时刻写死并注入固定时钟，
19	// 结论不依赖运行当天或真实时间等待。
20	var (
21		retroOldStart   = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
22		retroOldEnd     = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
23		retroHandoff    = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
24		retroAcceptedAt = time.Date(2026, 3, 15, 10, 0, 0, 0, time.UTC)
25	)
