27	// 场景中各笔报价各自使用独立的非空请求标识。
28	const (
29		retroIDOriginal = "retro-original-600" // 补登前已确认的 600 分报价
30		retroIDExpired  = "retro-old-expired"  // 补登后用新标识引用旧版
31		retroIDNew      = "retro-new-720"      // 补登后用新标识引用新版
32	)
33	
34	// newRetroactiveBookWithConfirmedQuote 建立补登场景的起点：
35	// 只登记旧版 seat-v1，时钟固定在 3 月 15 日 10 点，
36	// 此时旧版尚未被替代，用原标识以数量 4 取得 150 分单价、600 分总价的确认。
37	// 返回账本、推进时钟的函数、原请求与首次确认结果。
38	func newRetroactiveBookWithConfirmedQuote(t *testing.T) (*Book, func(time.Time), QuoteRequest, Outcome) {
39		t.Helper()
40		// 场景前提：交接点早于报价受理时刻，且受理时刻仍在旧版登记的有效期内。
41		if !retroHandoff.Before(retroAcceptedAt) {
42			t.Fatal("测试前提不成立：新版生效时刻应早于报价受理时刻")
43		}
44		if !retroAcceptedAt.Before(retroOldEnd) {
45			t.Fatal("测试前提不成立：报价受理时刻应早于旧版登记结束")
46		}
47	
48		now, setNow := fixedClock(retroAcceptedAt)
49		b := NewBook(WithClock(now))
50		oldEnd := retroOldEnd
51		if err := b.RegisterVersion(RegisterRequest{
52			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
53			Start: retroOldStart, End: &oldEnd,
54		}); err != nil {
55			t.Fatalf("register seat-v1: %v", err)
56		}
57	
58		req := QuoteRequest{
59			RequestID: retroIDOriginal, ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
60		}
61		first, err := b.Quote(req)
62		if err != nil {
63			t.Fatalf("旧版尚未被替代时报价应正常受理: %v", err)
64		}
65		if !first.Confirmed || first.UnitPrice != 150 || first.Total != 600 {
66			t.Fatalf("补登前报价应按 150 分确认 600 分: %+v", first)
67		}
68		if !first.AcceptedAt.Equal(retroAcceptedAt) || first.Reason != ReasonNone {
69			t.Fatalf("首次结果受理时刻/拒绝原因异常: %+v", first)
70		}
71		return b, setNow, req, first
72	}
73	
74	// registerRetroactiveReplacement 仍停在报价受理时刻补登新版 seat-v2：
75	// 单价 180 分，从 3 月 10 日零点起替代旧版，不填结束时间。
76	// 同项没有其他版本占用新版的有效时间，登记必须成功。
77	func registerRetroactiveReplacement(t *testing.T, b *Book) {
78		t.Helper()
79		if err := b.RegisterVersion(RegisterRequest{
80			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
81			Start: retroHandoff, Replaces: "seat-v1",
82		}); err != nil {
83			t.Fatalf("在受理时刻补登过去生效、且无其他版本占用其时间的新版应成功: %v", err)
84		}
85	}
