87	// 补登成功后：旧版登记结束仍是 3 月 31 日，实际有效结束被提前到 3 月 10 日，
88	// 新旧版本互相可见替代关系；新版从 3 月 10 日起持续有效。
89	func TestRetroactiveReplacementTruncatesOldVersion(t *testing.T) {
90		b, _, _, _ := newRetroactiveBookWithConfirmedQuote(t)
91		registerRetroactiveReplacement(t, b)
92	
93		views, err := b.ItemVersions("seat")
94		if err != nil {
95			t.Fatal(err)
96		}
97		if len(views) != 2 {
98			t.Fatalf("补登后应有两个版本，got %d: %+v", len(views), views)
99		}
100		old, nv := views[0], views[1]
101		if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" {
102			t.Fatalf("版本应按生效时刻排列为 v1/v2: %q, %q", old.VersionID, nv.VersionID)
103		}
104	
105		// 旧版：登记结束仍是 3 月 31 日（永不因后续登记改变），
106		// 实际结束提前到 3 月 10 日，且该点早于已确认报价的受理时刻。
107		if old.UnitPrice != 150 {
108			t.Fatalf("旧版单价被改写: %d", old.UnitPrice)
109		}
110		if old.End == nil || !old.End.Equal(retroOldEnd) {
111			t.Fatalf("旧版登记结束应仍为 3 月 31 日: %v", old.End)
112		}
113		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(retroHandoff) {
114			t.Fatalf("旧版实际结束应被提前到 3 月 10 日: %v", old.EffectiveEnd)
115		}
116		if !old.EffectiveEnd.Before(retroAcceptedAt) {
117			t.Fatalf("旧版实际结束应早于已确认报价的受理时刻: 实际结束=%v 受理时刻=%v",
118				old.EffectiveEnd, retroAcceptedAt)
119		}
120		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
121			t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q", old.Replaces, old.SupersededBy)
122		}
123	
124		// 新版：从 3 月 10 日起持续有效，登记结束与实际结束均为空，并保留替代来源。
125		if nv.UnitPrice != 180 || !nv.Start.Equal(retroHandoff) {
126			t.Fatalf("新版登记信息异常: %+v", nv)
127		}
128		if nv.End != nil || nv.EffectiveEnd != nil {
129			t.Fatalf("新版不填结束时间，两种结束都应为空: 登记结束=%v 实际结束=%v",
130				nv.End, nv.EffectiveEnd)
131		}
132		if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
133			t.Fatalf("新版替代关系异常: Replaces=%q SupersededBy=%q", nv.Replaces, nv.SupersededBy)
134		}
135	}
136	
137	// 补登之后按原标识 Lookup，或保持费率项、版本和数量不变再次报价，
138	// 都必须取回首次确认结果：来源仍是旧版，数量 4、单价 150、总价 600、
139	// 首次受理时刻 3 月 15 日 10 点全部保留，拒绝原因为空。
140	func TestRetroactiveReplacementPreservesConfirmedQuote(t *testing.T) {
141		b, _, req, first := newRetroactiveBookWithConfirmedQuote(t)
142		registerRetroactiveReplacement(t, b)
143	
144		assertOriginal600 := func(t *testing.T, got Outcome) {
145			t.Helper()
146			if got != first {
147				t.Fatalf("历史确认结果被补登改写: 首次=%+v 取回=%+v", first, got)
148			}
149			if got.Request != req {
150				t.Fatalf("历史结果来源应仍是旧版原请求: %+v vs %+v", got.Request, req)
151			}
152			if !got.Confirmed || got.UnitPrice != 150 || got.Total != 600 {
153				t.Fatalf("历史结果应保留确认与 600 分金额: %+v", got)
154			}
155			if !got.AcceptedAt.Equal(retroAcceptedAt) {
156				t.Fatalf("首次受理时刻应保留为 3 月 15 日 10 点: %v", got.AcceptedAt)
157			}
158			if got.Reason != ReasonNone {
159				t.Fatalf("已确认记录的拒绝原因应为空: %q", got.Reason)
160			}
161		}
162	
163		got, err := b.Lookup(retroIDOriginal)
164		if err != nil {
165			t.Fatalf("补登后原标识应仍可查询: %v", err)
166		}
167		assertOriginal600(t, got)
168	
169		// 原样重试同样返回首次结果，而不是因旧版实际结束被提前而改判拒绝或改用新版价格。
170		replay, err := b.Quote(req)
171		if err != nil {
172			t.Fatalf("原样重试不应返回错误: %v", err)
173		}
174		assertOriginal600(t, replay)
175	}
176	
177	// 仍在 3 月 15 日 10 点这一受理时刻：
178	// 用新标识引用旧版应正常受理后以 version_expired 拒绝，单价、总价为零；
179	// 用另一个新标识引用新版、数量 4，应按 180 分确认 720 分，来源指向新版；
180	// 两笔新报价都不能覆盖原来的 600 分记录。
181	func TestRetroactiveReplacementNewQuotesAtSameInstant(t *testing.T) {
182		b, setNow, _, first := newRetroactiveBookWithConfirmedQuote(t)
183		registerRetroactiveReplacement(t, b)
184		// 补登不推进时钟；显式固定在原受理时刻，确认补登后的当场判定不依赖真实时间。
185		setNow(retroAcceptedAt)
186	
187		// 新标识引用已被提前结束的旧版：正常受理（err 为空）后拒绝。
188		expiredReq := QuoteRequest{
189			RequestID: retroIDExpired, ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
190		}
191		expired, err := b.Quote(expiredReq)
192		if err != nil {
193			t.Fatalf("引用旧版是正常受理，err 应为空: %v", err)
194		}
195		if expired.Confirmed {
196			t.Fatalf("旧版实际结束已提前到受理时刻之前，不能确认: %+v", expired)
197		}
198		if expired.Reason != ReasonVersionExpired {
199			t.Fatalf("拒绝原因应为 version_expired, got %q", expired.Reason)
200		}
201		if expired.UnitPrice != 0 || expired.Total != 0 {
202			t.Fatalf("拒绝结果单价/总价应为零: 单价=%d 总价=%d", expired.UnitPrice, expired.Total)
203		}
204		if expired.Request != expiredReq {
205			t.Fatalf("拒绝结果必须保留指定的旧版来源与数量: %+v vs %+v", expired.Request, expiredReq)
206		}
207		if !expired.AcceptedAt.Equal(retroAcceptedAt) {
208			t.Fatalf("拒绝结果受理时刻应为当前受理时刻: %v", expired.AcceptedAt)
209		}
210	
211		// 另一个新标识引用新版：按 180 分确认 720 分。
212		newReq := QuoteRequest{
213			RequestID: retroIDNew, ItemID: "seat", VersionID: "seat-v2", Quantity: 4,
214		}
215		fresh, err := b.Quote(newReq)
216		if err != nil {
217			t.Fatalf("引用新版是正常受理，err 应为空: %v", err)
218		}
219		if !fresh.Confirmed || fresh.UnitPrice != 180 || fresh.Total != 720 {
220			t.Fatalf("新版报价应按 180 分确认 720 分: %+v", fresh)
221		}
222		if fresh.Request != newReq || fresh.Reason != ReasonNone {
223			t.Fatalf("新确认结果应指向新版原请求且无拒绝原因: %+v", fresh)
224		}
225		if !fresh.AcceptedAt.Equal(retroAcceptedAt) {
226			t.Fatalf("新确认结果受理时刻应为当前受理时刻: %v", fresh.AcceptedAt)
227		}
228	
229		// 新的拒绝与新的确认都不能覆盖原来的 600 分记录。
230		got, err := b.Lookup(retroIDOriginal)
231		if err != nil {
232			t.Fatal(err)
233		}
234		if got != first {
235			t.Fatalf("600 分原记录被新报价覆盖: 首次=%+v 取回=%+v", first, got)
236		}
237		// 三笔结果各按自己的标识取回，互不覆盖。
238		if gotExpired, err := b.Lookup(retroIDExpired); err != nil || gotExpired != expired {
239			t.Fatalf("拒绝记录应可按自己的标识原样取回: %+v (%v)", gotExpired, err)
240		}
241		if gotNew, err := b.Lookup(retroIDNew); err != nil || gotNew != fresh {
242			t.Fatalf("720 分确认应可按自己的标识原样取回: %+v (%v)", gotNew, err)
243		}
244	}
245	
246	// 沿用原标识只把版本改成新版：返回 ErrRequestIDConflict，
247	// 不产生新的确认价，也不改写原 600 分记录；原标识原样重试仍取回首次结果。
248	func TestRetroactiveReplacementRequestIDConflict(t *testing.T) {
249		b, _, req, first := newRetroactiveBookWithConfirmedQuote(t)
250		registerRetroactiveReplacement(t, b)
251	
252		conflictReq := req
253		conflictReq.VersionID = "seat-v2" // 只把版本改成新版，标识、费率项、数量不变
254		out, err := b.Quote(conflictReq)
255		if !errors.Is(err, ErrRequestIDConflict) {
256			t.Fatalf("沿用原标识改版本应返回 ErrRequestIDConflict, got %v", err)
257		}
258		if out != (Outcome{}) {
259			t.Fatalf("冲突时不应返回任何报价结果: %+v", out)
260		}
261	
262		// 原记录未被改写：Lookup 与原样重试取回的仍是首次 600 分确认。
263		got, err := b.Lookup(retroIDOriginal)
264		if err != nil {
265			t.Fatal(err)
266		}
267		if got != first {
268			t.Fatalf("冲突调用改写了原记录: 首次=%+v 取回=%+v", first, got)
269		}
270		replay, err := b.Quote(req)
271		if err != nil {
272			t.Fatalf("原请求内容未变，不应冲突: %v", err)
273		}
274		if replay != first {
275			t.Fatalf("冲突后原样重试应仍取回首次结果: 首次=%+v 取回=%+v", first, replay)
276		}
277	}
